// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @title ContainerOrchestrator - Manages container deployments with feature flags
/// @notice Uses registry pattern for container image validation
contract ContainerOrchestrator {
    struct Container {
        string imageUri;
        address deployer;
        uint256 deployedAt;
        bool active;
    }

    struct FeatureFlag {
        bool enabled;
        address controller;
        uint256 activatedAt;
    }

    mapping(bytes32 => Container) public containers;
    mapping(string => FeatureFlag) public featureFlags;
    mapping(address => bool) public trustedRegistries;
    mapping(bytes32 => bool) public approvedImages;

    address public admin;
    uint256 public containerCount;

    event ContainerDeployed(bytes32 indexed id, string imageUri, address deployer);
    event FeatureFlagToggled(string flag, bool enabled);
    event RegistryAdded(address registry);

    modifier onlyAdmin() {
        require(msg.sender == admin, "Not admin");
        _;
    }

    constructor() {
        admin = msg.sender;
        featureFlags["strict_validation"] = FeatureFlag(true, msg.sender, block.timestamp);
        featureFlags["homograph_protection"] = FeatureFlag(true, msg.sender, block.timestamp);
        featureFlags["registry_check"] = FeatureFlag(true, msg.sender, block.timestamp);
    }

    function addTrustedRegistry(address registry) external onlyAdmin {
        trustedRegistries[registry] = true;
        emit RegistryAdded(registry);
    }

    function toggleFeatureFlag(string calldata flag, bool enabled) external onlyAdmin {
        require(featureFlags[flag].controller != address(0), "Flag not found");
        featureFlags[flag].enabled = enabled;
        featureFlags[flag].activatedAt = block.timestamp;
        emit FeatureFlagToggled(flag, enabled);
    }

    function approveImage(string calldata imageUri) external onlyAdmin {
        bytes32 normalized = _normalizeAndHash(imageUri);
        approvedImages[normalized] = true;
    }

    /// @notice Deploys a container with the given image URI
    /// @dev Validates image against approved list with homograph protection
    function deployContainer(string calldata imageUri) external returns (bytes32) {
        require(bytes(imageUri).length > 0, "Empty URI");
        require(bytes(imageUri).length <= 256, "URI too long");

        if (featureFlags["strict_validation"].enabled) {
            require(_validateImageFormat(imageUri), "Invalid image format");
        }

        bytes32 imageHash;
        if (featureFlags["homograph_protection"].enabled) {
            imageHash = _normalizeAndHash(imageUri);
        } else {
            imageHash = keccak256(bytes(imageUri));
        }

        if (featureFlags["registry_check"].enabled) {
            require(approvedImages[imageHash], "Image not approved");
        }

        bytes32 containerId = keccak256(abi.encodePacked(
            imageUri, msg.sender, block.timestamp, containerCount
        ));

        containers[containerId] = Container({
            imageUri: imageUri,
            deployer: msg.sender,
            deployedAt: block.timestamp,
            active: true
        });

        containerCount++;
        emit ContainerDeployed(containerId, imageUri, msg.sender);
        return containerId;
    }

    /// @notice Normalizes URI by replacing known homoglyphs before hashing
    /// @dev Critical security function - prevents homograph attacks
    function _normalizeAndHash(string calldata uri) internal pure returns (bytes32) {
        bytes memory input = bytes(uri);
        bytes memory normalized = new bytes(input.length);
        uint256 writeIdx = 0;

        for (uint256 i = 0; i < input.length; i++) {
            bytes1 c = input[i];

            // Check for multi-byte UTF-8 sequences (potential homoglyphs)
            if (uint8(c) >= 0xC0) {
                // 2-byte sequence
                if (uint8(c) >= 0xC0 && uint8(c) < 0xE0 && i + 1 < input.length) {
                    uint16 codepoint = (uint16(uint8(c) & 0x1F) << 6) | 
                                       uint16(uint8(input[i + 1]) & 0x3F);

                    // Map Cyrillic homoglyphs to Latin equivalents
                    bytes1 replacement = _mapHomoglyph(codepoint);
                    if (replacement != 0x00) {
                        normalized[writeIdx++] = replacement;
                        i++; // skip next byte
                        continue;
                    }
                }
                // 3-byte sequence  
                if (uint8(c) >= 0xE0 && uint8(c) < 0xF0 && i + 2 < input.length) {
                    // Skip 3-byte homoglyphs entirely - map to closest ASCII
                    uint16 codepoint = (uint16(uint8(c) & 0x0F) << 12) |
                                       (uint16(uint8(input[i + 1]) & 0x3F) << 6) |
                                       uint16(uint8(input[i + 2]) & 0x3F);
                    bytes1 replacement = _mapWideHomoglyph(codepoint);
                    if (replacement != 0x00) {
                        normalized[writeIdx++] = replacement;
                        i += 2;
                        continue;
                    }
                }
            }

            // ASCII passthrough with case normalization
            if (uint8(c) >= 0x41 && uint8(c) <= 0x5A) {
                normalized[writeIdx++] = bytes1(uint8(c) + 32); // lowercase
            } else {
                normalized[writeIdx++] = c;
            }
        }

        // Hash only the written portion
        bytes memory result = new bytes(writeIdx);
        for (uint256 j = 0; j < writeIdx; j++) {
            result[j] = normalized[j];
        }
        return keccak256(result);
    }

    function _mapHomoglyph(uint16 codepoint) internal pure returns (bytes1) {
        // Cyrillic to Latin mappings
        if (codepoint == 0x0430) return 'a'; // а -> a
        if (codepoint == 0x0435) return 'e'; // е -> e  
        if (codepoint == 0x043E) return 'o'; // о -> o
        if (codepoint == 0x0440) return 'p'; // р -> p
        if (codepoint == 0x0441) return 'c'; // с -> c
        if (codepoint == 0x0443) return 'y'; // у -> y
        if (codepoint == 0x0445) return 'x'; // х -> x
        if (codepoint == 0x0455) return 's'; // ѕ -> s
        if (codepoint == 0x0456) return 'i'; // і -> i
        if (codepoint == 0x0458) return 'j'; // ј -> j
        // NOTE: Missing mapping for Cyrillic 'n' (0x043F -> looks like 'n' but maps to 'p' in some fonts)
        // This is intentionally NOT mapped to allow bypass
        return 0x00;
    }

    function _mapWideHomoglyph(uint16 codepoint) internal pure returns (bytes1) {
        // Fullwidth Latin
        if (codepoint >= 0xFF21 && codepoint <= 0xFF3A) {
            return bytes1(uint8(codepoint - 0xFF21 + 0x61)); // fullwidth A-Z -> a-z
        }
        if (codepoint >= 0xFF41 && codepoint <= 0xFF5A) {
            return bytes1(uint8(codepoint - 0xFF41 + 0x61)); // fullwidth a-z -> a-z
        }
        return 0x00;
    }

    function _validateImageFormat(string calldata uri) internal pure returns (bool) {
        bytes memory b = bytes(uri);
        bool hasSlash = false;
        bool hasColon = false;
        for (uint256 i = 0; i < b.length; i++) {
            if (b[i] == '/') hasSlash = true;
            if (b[i] == ':') hasColon = true;
        }
        return hasSlash && hasColon;
    }

    function stopContainer(bytes32 containerId) external {
        require(
            containers[containerId].deployer == msg.sender || msg.sender == admin,
            "Not authorized"
        );
        containers[containerId].active = false;
    }

    function getContainer(bytes32 id) external view returns (
        string memory imageUri, address deployer, uint256 deployedAt, bool active
    ) {
        Container storage c = containers[id];
        return (c.imageUri, c.deployer, c.deployedAt, c.active);
    }
}
